# name: mumble_intermediate_feature_rate
# description: Proportion of choices for objects with strictly intermediate feature counts among mumble trials where the display contains objects of at least three distinct feature counts.
def test_statistic(df):
    unique_objs = df[df['query'] == 'prior']['objects'].drop_duplicates()
    inter_map = {}
    for s in unique_objs:
        objs = json.loads(s)
        counts = [sum(o) for o in objs]
        unique_counts = sorted(list(set(counts)))
        if len(unique_counts) >= 3:
            intermediate = set(unique_counts[1:-1])
            classes = set(objs.index(o) for o in objs if sum(o) in intermediate)
            inter_map[s] = classes
    sub_df = df[(df['query'] == 'prior') & (df['objects'].isin(inter_map))]
    if len(sub_df) == 0:
        return 0.0
    is_inter = [c in inter_map[o] for o, c in zip(sub_df['objects'], sub_df['choice'])]
    return float(np.mean(is_inter))

# name: competitor_with_redundant_features_rate
# description: Proportion of choices for the overspecified competitor object in utterance trials where the competitor possesses at least two redundant alternative features.
def test_statistic(df):
    unique_pairs = df[['objects', 'utterance']].drop_duplicates()
    comp_map = {}
    for _, r in unique_pairs.iterrows():
        utt = r['utterance']
        if pd.isna(utt):
            continue
        u = int(utt)
        objs = json.loads(r['objects'])
        n_feats = len(objs[0])
        cols = [[objs[i][f] for i in range(len(objs))] for f in range(n_feats)]
        classes = {}
        for i, o in enumerate(objs):
            if o[u] == 1:
                first = objs.index(o)
                classes[first] = classes.get(first, 0) + 1
        if len(classes) == 2:
            c1, c2 = list(classes.keys())
            cnt1, cnt2 = sum(objs[c1]), sum(objs[c2])
            if cnt1 != cnt2:
                comp = c1 if cnt1 > cnt2 else c2
                comp_other_feats = [f for f in range(n_feats) if f != u and objs[comp][f] == 1]
                has_red = False
                for f1 in comp_other_feats:
                    for f2 in comp_other_feats:
                        if f1 < f2 and cols[f1] == cols[f2]:
                            has_red = True
                            break
                if has_red:
                    comp_map[(r['objects'], u)] = comp
    utts = df['utterance'].fillna(-1).astype(int)
    keys = list(zip(df['objects'], utts))
    targets = [comp_map.get(k, -1) for k in keys]
    mask = [t != -1 for t in targets]
    if not any(mask):
        return 0.0
    sub_df = df[mask]
    sub_targets = np.array([t for t in targets if t != -1])
    return float(np.mean(sub_df['choice'].to_numpy() == sub_targets))

# name: duplicate_competitor_choice_rate
# description: Proportion of choices for the competitor class among utterance trials where the heard word is true of a unique singleton target and a competitor object that has duplicate copies in the scene.
def test_statistic(df):
    unique_pairs = df[['objects', 'utterance']].drop_duplicates()
    comp_map = {}
    for _, r in unique_pairs.iterrows():
        utt = r['utterance']
        if pd.isna(utt):
            continue
        u = int(utt)
        objs = json.loads(r['objects'])
        classes_with_u = {}
        for idx, o in enumerate(objs):
            if o[u] == 1:
                first = objs.index(o)
                classes_with_u[first] = classes_with_u.get(first, 0) + 1
        if len(classes_with_u) == 2:
            c_single = [c for c, count in classes_with_u.items() if count == 1]
            c_dup = [c for c, count in classes_with_u.items() if count > 1]
            if len(c_single) == 1 and len(c_dup) == 1:
                comp_map[(r['objects'], u)] = c_dup[0]
    utts = df['utterance'].fillna(-1).astype(int)
    keys = list(zip(df['objects'], utts))
    targets = [comp_map.get(k, -1) for k in keys]
    mask = [t != -1 for t in targets]
    if not any(mask):
        return 0.0
    sub_df = df[mask]
    sub_targets = np.array([t for t in targets if t != -1])
    return float(np.mean(sub_df['choice'].to_numpy() == sub_targets))

# name: false_feature_choice_rate
# description: Proportion of choices for an object of which the heard utterance is false across all utterance trials.
def test_statistic(df):
    unique_pairs = df[['objects', 'utterance']].drop_duplicates()
    false_map = {}
    for _, r in unique_pairs.iterrows():
        utt = r['utterance']
        if pd.isna(utt):
            continue
        u = int(utt)
        objs = json.loads(r['objects'])
        false_classes = set()
        for idx, o in enumerate(objs):
            if o[u] == 0:
                false_classes.add(objs.index(o))
        false_map[(r['objects'], u)] = false_classes
    utts = df['utterance'].fillna(-1).astype(int)
    keys = list(zip(df['objects'], utts))
    choices = df['choice'].to_numpy()
    is_false = [k in false_map and c in false_map[k] for k, c in zip(keys, choices)]
    utt_mask = [k in false_map for k in keys]
    if not any(utt_mask):
        return 0.0
    return float(np.sum(is_false) / np.sum(utt_mask))

