# name: mumble_empty_object_rate
# description: Proportion of choices for the featureless object among four-object mumble trials containing at least one featureless object.
def test_statistic(df):
    unique_objs = df[df['query'] == 'prior']['objects'].drop_duplicates()
    empty_map = {}
    for s in unique_objs:
        objs = json.loads(s)
        if len(objs) == 4 and any(sum(o) == 0 for o in objs):
            first_empty = [objs.index(o) for o in objs if sum(o) == 0][0]
            empty_map[s] = first_empty
    sub_df = df[(df['query'] == 'prior') & (df['objects'].isin(empty_map))]
    if len(sub_df) == 0:
        return 0.0
    targets = np.array([empty_map[o] for o in sub_df['objects']])
    return float(np.mean(sub_df['choice'].to_numpy() == targets))

# name: mumble_pairwise_rich_object_rate
# description: Proportion of choices for the object with more features among two-object mumble trials with unequal feature counts.
def test_statistic(df):
    unique_objs = df[df['query'] == 'prior']['objects'].drop_duplicates()
    rich_map = {}
    for s in unique_objs:
        objs = json.loads(s)
        if len(objs) == 2:
            cnt0, cnt1 = sum(objs[0]), sum(objs[1])
            if cnt0 != cnt1:
                rich_map[s] = 0 if cnt0 > cnt1 else 1
    sub_df = df[(df['query'] == 'prior') & (df['objects'].isin(rich_map))]
    if len(sub_df) == 0:
        return 0.0
    targets = np.array([rich_map[o] for o in sub_df['objects']])
    return float(np.mean(sub_df['choice'].to_numpy() == targets))

# name: two_object_scalar_target_rate
# description: Proportion of choices for the minimal target object among two-object utterance trials where the heard word is true of both objects.
def test_statistic(df):
    unique_pairs = df[['objects', 'utterance']].drop_duplicates()
    target_map = {}
    for _, r in unique_pairs.iterrows():
        utt = r['utterance']
        if pd.isna(utt):
            continue
        u = int(utt)
        objs = json.loads(r['objects'])
        if len(objs) == 2 and objs[0][u] == 1 and objs[1][u] == 1:
            cnt0, cnt1 = sum(objs[0]), sum(objs[1])
            if cnt0 != cnt1:
